      {"@type":"ListItem","position":2,"name":"Preparation","item":"https://okoth.hu/"},
      {"@type":"ListItem","position":3,"name":"Plot suitability","item":"https://okoth.hu/telekalkalmassag"},
      {"@type":"ListItem","position":4,"name":"Wells and protective distance","item":"https://okoth.hu/projekt-elokeszites/kut-es-vedotavolsag"}
      ]
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Does a well rule the system out from the start?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Not in itself. The sealed tank and the point where the treated water is disposed of are separate objects, and it is usually the latter that raises the real question. Judging it, however, requires knowing the well's type, its use, its position and the area's water base protection situation."
          }
        },
        {
          "@type": "Question",
          "name": "Why do you not say how many metres are needed from the well?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Because a single figure would not be true in every situation. Judging the distance depends on the well's type and depth, the direction of groundwater flow, the area's sensitivity classification, and whether a designated water base protection area is involved. A general number here would mislead more than it would help."
          }
        },
        {
          "@type": "Question",
          "name": "Does a neighbour's well have to be taken into account?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. For water protection purposes it is not the plot boundary that governs but the actual relationship between the well and the point of disposal. Neighbouring wells are therefore worth marking on the site plan."
          }
        },
        {
          "@type": "Question",
          "name": "There is an old, unused well on the plot. Does it matter?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It can. A well no longer in use but not sealed may remain an open route towards the subsurface water. Its position and condition are worth reporting, because they affect the expert assessment."
          }
        }
      ]
    }
  ]
}

